return ['domain'=>'pnscripts-product-tabs','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'bg_BG','project-id-version'=>'PN Product Tabs 1.0.1','pot-creation-date'=>'2026-10-05T12:35:24+00:00','po-revision-date'=>'2026-10-04 00:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PN Product Tabs – Custom Tabs & FAQ'=>'PN Product Tabs – Custom Tabs & FAQ','https://pnscripts.com/marketplace/pn-product-tabs'=>'https://pnscripts.com/marketplace/pn-product-tabs','Custom product tabs per product, reusable global tabs by category or tag, FAQ tabs with optional FAQPage schema, rename, reorder or hide the default tabs, and a one-click importer from YIKES Custom Product Tabs. Works in classic and block themes.'=>'Собствени раздели за всеки продукт, глобални раздели за категории или етикети, раздели с ЧЗВ и FAQPage schema, преименуване, подреждане и скриване на стандартните раздели и импорт с едно кликване от YIKES Custom Product Tabs. Работи с класически и блокови теми.','PN Scripts'=>'PN Scripts','https://pnscripts.com'=>'https://pnscripts.com','Tab settings'=>'Настройки на разделите','Tab type'=>'Вид на раздела','Rich text: the content written in the editor above'=>'Текст: съдържанието от редактора по-горе','FAQ: questions and answers below'=>'ЧЗВ: въпросите и отговорите по-долу','Add question'=>'Добави въпрос','Publish as FAQPage structured data'=>'Публикувай като структурирани данни FAQPage','Show this tab on'=>'Показвай раздела на','All products'=>'Всички продукти','Products in these categories or with these tags'=>'Продукти в тези категории или с тези етикети','Only products where I add it (Product data → Custom tabs)'=>'Само продукти, в които го добавя (Данни за продукта → Собствени раздели)','Categories (subcategories included)'=>'Категории (включително подкатегориите)','Choose categories…'=>'Изберете категории…','Tags'=>'Етикети','Choose tags…'=>'Изберете етикети…','Position (priority)'=>'Позиция (приоритет)','Lower numbers come first. WooCommerce uses 10 for Description, 20 for Additional information and 30 for Reviews (change these under Products → Tab settings).'=>'По-малките числа са първи. WooCommerce използва 10 за Описание, 20 за Допълнителна информация и 30 за Отзиви (променят се в Продукти → Настройки на разделите).','Question'=>'Въпрос','Answer'=>'Отговор','Remove question'=>'Премахни въпроса','Shown on'=>'Показва се на','Type'=>'Вид','Priority'=>'Приоритет','FAQ'=>'ЧЗВ','Rich text'=>'Текст','Products where added'=>'Продукти, в които е добавен','No categories or tags chosen'=>'Няма избрани категории или етикети','Custom tabs'=>'Собствени раздели','Remove this tab? It is deleted when you update the product.'=>'Да се премахне ли разделът? Изтрива се, когато обновите продукта.','(no title)'=>'(без заглавие)','Tabs shown on this product, in this order (drag to reorder). Rich-text tabs accept anything the editor does; FAQ tabs show questions as an accessible list and can publish FAQPage structured data.'=>'Раздели на този продукт в този ред (плъзнете, за да пренаредите). Текстовите раздели приемат всичко, което поддържа редакторът; разделите с ЧЗВ показват въпросите като достъпен списък и могат да публикуват структурирани данни FAQPage.','No custom tabs on this product yet.'=>'Този продукт още няма собствени раздели.','Add tab'=>'Добави раздел','Add FAQ tab'=>'Добави раздел с ЧЗВ','Global tab to add'=>'Глобален раздел за добавяне','Add a global tab…'=>'Добави глобален раздел…','Add'=>'Добави','Manage global tabs'=>'Управление на глобалните раздели','Global tabs shown automatically'=>'Глобални раздели, показвани автоматично','Hide "%s" on this product'=>'Скрий „%s“ на този продукт','WooCommerce tabs on this product'=>'Раздели на WooCommerce в този продукт','(deleted global tab)'=>'(изтрит глобален раздел)','Global'=>'Глобален','Drag to reorder'=>'Плъзнете, за да пренаредите','Imported'=>'Импортиран','Show'=>'Показвай','Remove'=>'Премахни','Content comes from the global tab and updates everywhere when you edit it.'=>'Съдържанието идва от глобалния раздел и се обновява навсякъде, когато го редактирате.','Edit global tab'=>'Редактирай глобалния раздел','Tab title'=>'Заглавие на раздела','Tab content'=>'Съдържание на раздела','Description'=>'Описание','Additional information'=>'Допълнителна информация','Reviews'=>'Отзиви','Product tab settings'=>'Настройки на продуктовите раздели','Settings'=>'Настройки','Global tabs'=>'Глобални раздели','Import the YIKES tabs now? YIKES data is not changed and you can undo the import.'=>'Да се импортират ли разделите от YIKES сега? Данните на YIKES не се променят и можете да отмените импорта.','Remove all tabs created by the import (tabs you added yourself stay)?'=>'Да се премахнат ли всички раздели, създадени от импорта (добавените от вас остават)?','Working… %d products handled'=>'Обработка… %d обработени продукта','The request failed. Reload the page and try again.'=>'Заявката беше неуспешна. Презаредете страницата и опитайте отново.','Dry run finished: nothing was changed. These numbers are what an import will do.'=>'Пробното изпълнение приключи: нищо не е променено. Тези числа показват какво ще направи импортът.','Import finished. Check a few product pages, then deactivate YIKES Custom Product Tabs.'=>'Импортът приключи. Проверете няколко продуктови страници и след това деактивирайте YIKES Custom Product Tabs.','Import removed.'=>'Импортът е премахнат.','… and %d more notes like these.'=>'… и още %d подобни бележки.','Products with YIKES tabs'=>'Продукти с раздели от YIKES','YIKES saved tabs'=>'Запазени раздели в YIKES','Global tabs to create / created'=>'Глобални раздели за създаване / създадени','Saved tabs imported before (left as they are)'=>'Запазени раздели, импортирани преди (остават непроменени)','Products to import / imported'=>'Продукти за импорт / импортирани','Products unchanged since the last import (skipped)'=>'Продукти без промяна от последния импорт (пропуснати)','Product tabs copied'=>'Копирани продуктови раздели','Product tabs linked to a global tab'=>'Продуктови раздели, свързани с глобален раздел','Tabs without a title (imported switched off)'=>'Раздели без заглавие (импортирани изключени)','Tabs hidden by a duplicate title in YIKES (imported switched off)'=>'Раздели, скрити от дублирано заглавие в YIKES (импортирани изключени)','Default tabs YIKES replaced (hidden on those products)'=>'Стандартни раздели, заменени от YIKES (скрити на тези продукти)','Imported global tabs removed'=>'Премахнати импортирани глобални раздели','Products cleaned'=>'Почистени продукти','You are not allowed to import tabs.'=>'Нямате права да импортирате раздели.','Import from YIKES'=>'Импорт от YIKES','WooCommerce tabs'=>'Раздели на WooCommerce','Rename, reorder or hide the standard tabs on every product (single products can hide them too, under Product data → Custom tabs). Leave a title empty to keep WooCommerce\'s title; in the Reviews title, %s becomes the number of reviews.'=>'Преименувайте, пренаредете или скрийте стандартните раздели на всички продукти (отделни продукти също могат да ги скрият в Данни за продукта → Собствени раздели). Оставете заглавието празно, за да запазите заглавието на WooCommerce; в заглавието на Отзиви %s се заменя с броя на отзивите.','Tab'=>'Раздел','Title'=>'Заглавие','Priority of product tabs'=>'Приоритет на продуктовите раздели','The first tab added on a product gets this priority, the next one +1, and so on. 25 places them between Additional information and Reviews. Global tabs have their own priority.'=>'Първият раздел на продукта получава този приоритет, следващият +1 и т.н. 25 ги поставя между Допълнителна информация и Отзиви. Глобалните раздели имат собствен приоритет.','Display'=>'Показване','Keep Reviews as the last tab'=>'Отзиви винаги като последен раздел','Repeat the tab title as a heading inside the tab (classic tabs; never inside accordions)'=>'Повтаряй заглавието като заглавие в раздела (класически раздели; никога в акордеони)','Output FAQPage structured data for FAQ tabs that allow it (turn off if your SEO plugin already adds FAQ markup)'=>'Извеждай структурирани данни FAQPage за разделите с ЧЗВ, които го позволяват (изключете, ако SEO разширението ви вече добавя FAQ маркиране)','While YIKES Custom Product Tabs is still active, hide its copy of tabs that were imported'=>'Докато YIKES Custom Product Tabs е активен, скривай неговото копие на импортираните раздели','Uninstall'=>'Деинсталиране','Delete all tabs and settings of this plugin when it is deleted from the Plugins screen'=>'Изтрий всички раздели и настройки на това разширение, когато бъде изтрито от екрана Разширения','Off by default, so deleting and reinstalling the plugin keeps your tabs. YIKES data is never touched.'=>'Изключено по подразбиране, така че изтриването и повторното инсталиране запазва разделите. Данните на YIKES никога не се променят.','Copies the tabs of "Custom Product Tabs for WooCommerce" by YIKES: every product\'s tabs (in the same order, with the same content) and the saved tabs, which become global tabs. Products that used a saved tab are linked to the new global tab, so editing it updates them all. Saved tabs that the YIKES Pro add-on assigned to all products or to categories/tags keep those rules.'=>'Копира разделите на „Custom Product Tabs for WooCommerce“ от YIKES: разделите на всеки продукт (в същия ред и със същото съдържание) и запазените раздели, които стават глобални. Продуктите, използвали запазен раздел, се свързват с новия глобален раздел, така че редакцията му обновява всички. Запазените раздели, които YIKES Pro е задал за всички продукти или за категории/етикети, запазват тези правила.','YIKES data is only read. Nothing is changed or deleted, and YIKES keeps working until you deactivate it.'=>'Данните на YIKES само се четат. Нищо не се променя или изтрива и YIKES продължава да работи, докато не го деактивирате.','Running it again is safe: tabs are never duplicated, and products whose YIKES tabs did not change are skipped.'=>'Повторното изпълнение е безопасно: разделите не се дублират, а продуктите без промени в YIKES се пропускат.','Tabs YIKES never showed (no title, or hidden by another tab with the same title) are imported switched off and listed below.'=>'Разделите, които YIKES никога не е показвал (без заглавие или скрити от друг раздел със същото заглавие), се импортират изключени и са изброени по-долу.','Large catalogues are handled in batches of 100 products. Command line: wp pnscripts-product-tabs import-yikes --dry-run'=>'Големите каталози се обработват на партиди по 100 продукта. Команден ред: wp pnscripts-product-tabs import-yikes --dry-run','Found:'=>'Намерени:','%d product with YIKES tabs'=>'%d продукт с раздели от YIKES' . "\0" . '%d продукта с раздели от YIKES','YIKES plugin active'=>'разширението YIKES е активно','YIKES plugin not active (data can still be imported)'=>'разширението YIKES не е активно (данните пак могат да се импортират)','last import: %s'=>'последен импорт: %s','Dry run (change nothing)'=>'Пробно изпълнение (без промени)','Import now'=>'Импортирай сега','Undo import'=>'Отмени импорта','Notes'=>'Бележки','PN Product Tabs found tabs from Custom Product Tabs for WooCommerce (YIKES). Import them in one click; YIKES data stays untouched.'=>'PN Product Tabs откри раздели от Custom Product Tabs for WooCommerce (YIKES). Импортирайте ги с едно кликване; данните на YIKES остават непокътнати.','Review the import'=>'Прегледай импорта','Dismiss'=>'Скрий','Saved tab #%d has no title and was skipped.'=>'Запазеният раздел №%d няма заглавие и е пропуснат.','Saved tab "%1$s" was assigned by the taxonomy "%2$s", which is not supported; it is imported for the categories and tags only.'=>'Запазеният раздел „%1$s“ е бил зададен по таксономията „%2$s“, която не се поддържа; импортира се само за категориите и етикетите.','Product #%d: a tab without a title (never shown by YIKES) was imported switched off.'=>'Продукт №%d: раздел без заглавие (никога не показван от YIKES) е импортиран изключен.','Product #%1$d: the tab "%2$s" was hidden by a later tab with the same title in YIKES; it was imported switched off.'=>'Продукт №%1$d: разделът „%2$s“ е бил скрит от по-късен раздел със същото заглавие в YIKES; импортиран е изключен.','PN Product Tabs needs WooCommerce %s or newer to be active.'=>'PN Product Tabs изисква активен WooCommerce %s или по-нов.','Global product tabs'=>'Глобални продуктови раздели','Global product tab'=>'Глобален продуктов раздел','Product tabs'=>'Продуктови раздели','Add global tab'=>'Добави глобален раздел','New global tab'=>'Нов глобален раздел','Search global tabs'=>'Търси в глобалните раздели','No global tabs yet.'=>'Още няма глобални раздели.','No global tabs in the trash.'=>'Няма глобални раздели в кошчето.','Global tab updated.'=>'Глобалният раздел е обновен.','Global tab published.'=>'Глобалният раздел е публикуван.','Reusable tabs shown on all products, on products in chosen categories or tags, or where added manually.'=>'Раздели за многократна употреба, показвани на всички продукти, на продукти в избрани категории или етикети, или там, където са добавени ръчно.','Sorry, you are not allowed to view global product tabs.'=>'Нямате права да преглеждате глобалните продуктови раздели.']];